INSERT INTO document_vectors (id, content, embedding) VALUES ('01a0a12a-a6c8-7ae0-bf8a-a037ca2228cb', '---

## 1.

Defining Investment Versus Speculation

Graham opens his framework by establishing a strict boundary between an investment operation and a speculative maneuver. According to Graham, an investment operation requires three conditions: thorough fundamental analysis, a guaranteed safety of principal, and a satisfactory expected return. Any operation that fails to meet all three of these conditions is classified as speculation.', VEC_FromText('[0.0075416565, 0.046295166, 0.11743164, 0.042907715, -0.008956909, 0.0032081604, 0.021362305, 0.024307251, 0.101501465, -0.003929138, 0.08166504, -0.0073928833, 0.039520264, -0.014968872, 0.08508301, 0.030914307, -0.074645996, -0.03881836, 0.041534424, 0.10864258, 9.279251E-4, 0.08630371, -0.08392334, 0.03024292, -0.025619507, -0.0769043, -0.015426636, 0.06021118, -0.0021076202, -0.056884766, 0.072753906, -0.0040512085, -0.06488037, 0.007835388, 0.011177063, -0.028060913, -0.055603027, 0.010787964, 0.099365234, 0.05822754, -0.06951904, -0.019744873, -0.09576416, -8.993149E-4, 0.02154541, 0.055267334, -0.06088257, -0.026992798, -0.046051025, 0.04284668, -0.043518066, -0.025970459, 0.08465576, 0.059265137, 0.007736206, 0.035125732, -0.10089111, 0.006526947, -0.009063721, 0.03933716, 0.091308594, -0.0048065186, 0.05493164, 0.028518677, -0.06762695, -0.057281494, 0.022109985, 0.05419922, -0.026870728, -0.015525818, -0.0501709, -0.059143066, 0.010917664, 0.008628845, -0.06854248, 0.012817383, 0.0051956177, -0.0054969788, 0.034729004, 0.002544403, 0.025848389, -0.028060913, -0.036010742, -0.01322937, -0.033599854, 0.001335144, -0.029647827, -0.0060157776, -0.09893799, -0.10357666, -0.035491943, 0.10913086, 0.0413208, 0.005645752, -0.022354126, -0.035339355, 0.007083893, 0.04660034, -0.072509766, 0.026931763, 0.036499023, -0.016189575, -0.028121948, -0.017532349, 0.07775879, -0.0074157715, -0.113098145, 0.020904541, -0.026275635, -0.017715454, -0.07409668, 0.014945984, -0.08001709, 0.09088135, 0.025924683, -0.043060303, -0.14880371, -0.02859497, -0.0049972534, -0.0050086975, 0.