INSERT INTO document_vectors (id, content, embedding) VALUES ('01a0a12a-a968-7cbb-b6b5-442b611c004a', 'Speculation involves buying assets based on price momentum, market rumors, or unverified expectations of future price appreciation. While speculation is a natural part of financial markets, Graham warns that confusion between investing and speculating is the primary cause of severe financial loss. Investors must maintain complete separation between speculative funds and true investment capital.

---

