INSERT INTO document_vectors (id, content, embedding) VALUES ('01a0a12a-aa3b-75b6-b763-5e61420edc4d', '---

## 2.

The Allegory of Mr. Market

To illustrate market volatility and investor psychology, Graham introduces the concept of "Mr. Market". Imagine owning a share in a private business alongside an emotional partner named Mr. Market. Every day, Mr. Market offers to buy your share or sell you his share at a price driven by his shifting moods.', VEC_FromText('[0.027511597, -0.03869629, 0.062408447, 0.046539307, -0.042938232, 0.006565094, 0.059326172, 0.09490967, 0.01524353, -0.00390625, 0.09429932, -0.07873535, -0.013839722, -0.05218506, 0.06573486, 0.02734375, -0.056732178, -0.055541992, -0.022369385, 0.052246094, -0.035186768, 0.087890625, -0.032958984, 0.06384277, -0.025299072, -0.0814209, -0.054840088, 0.060821533, 0.018966675, -0.01663208, 0.09173584, -0.039245605, 0.019088745, -0.018203735, -0.03250122, 0.027526855, -0.070373535, -0.043395996, 0.072265625, 0.0027599335, -0.0032730103, -0.037902832, 0.0032348633, 0.12182617, 0.08166504, 0.035003662, -0.008857727, -0.10064697, 0.030456543, 0.06402588, -0.02217102, -0.023406982, 0.0368042, 0.043823242, -0.02229309, -0.030288696, -0.05065918, 0.048950195, 0.053497314, 0.022384644, 0.026626587, 0.040893555, -0.050994873, -0.025054932, -0.028320312, -0.10406494, -0.02947998, 0.037597656, -0.07397461, 0.061401367, 0.04449463, 0.032836914, -0.029769897, 0.04269409, -0.011657715, -0.055114746, -0.02609253, -3.874302E-4, 0.024230957, 0.0058555603, -0.012138367, 7.095337E-4, 0.03277588, 0.10119629, 0.057556152, -0.09313965, -0.028701782, 0.036132812, -0.02659607, -0.0014705658, -0.0062713623, 0.00932312, -0.010368347, 0.03277588, 0.018295288, -0.045684814, -0.013465881, 0.07946777, -0.043060303, 0.022613525, 0.02558899, -0.024536133, -0.046691895, 0.057037354, 0.09173584, 0.038635254, 0.01424408, -0.02406311, -0.107055664, 0.061584473, -0.2010498, 0.072265625, 0.042510986, -0.0077590942, -0.051452637, -0.024261475, -0.06817627, 0.027694702, 0.007873535, -0.06555176, -0.028060913, -0.05770874, 0.05215454, -0.057891846, 0.022232056, 0.053771973, -0.02508545, 0