INSERT INTO document_vectors (id, content, embedding) VALUES ('01a0a12a-afc1-746e-ba26-3174248fc3fa', 'On days when Mr. Market is euphoric, he quotes high prices. On days when he is pessimistic, he offers shares at steep discounts. The core insight of the allegory is that Mr. Market exists to serve the investor, not to guide them. Market quotations are pricing choices to be exploited when prices are low, ignored when prices are unreasonable, and never treated as indicators of underlying business value.

---

