INSERT INTO document_vectors (id, content, embedding) VALUES ('01a0a12a-b096-7808-bcdd-f408d15f372a', '---

## 3.

The Margin of Safety

The Margin of Safety is the central technical rule of value investing. It is defined as the quantitative gap between the intrinsic value of a business and the current market price of its stock.

$$\text{Margin of Safety} = \text{Intrinsic Value} - \text{Market Price}$$', VEC_FromText('[0.02470398, 0.08087158, 0.035186768, 0.050964355, 0.03250122, 0.033325195, 0.011665344, 0.014480591, 0.09527588, 0.016616821, 0.08111572, -0.043884277, -0.060333252, -0.043426514, 0.124694824, 0.054138184, -0.029403687, -0.040893555, 0.029129028, 0.026855469, -0.022033691, 0.06384277, 0.0079956055, 0.047729492, -0.026321411, -0.05130005, -0.015113831, 0.0061302185, 0.010017395, -0.002456665, 0.1204834, -0.053649902, -0.02545166, -0.03164673, 0.015823364, 0.05029297, -0.024414062, 0.0021800995, 0.014572144, -0.046783447, -0.042388916, 4.8017502E-4, -0.015022278, -0.015571594, 0.075683594, 9.7322464E-4, 0.027297974, -0.029464722, 0.017288208, 0.021469116, -0.09423828, -0.03930664, 0.08306885, 0.018035889, 0.045074463, 0.05807495, -0.034698486, 0.08093262, 0.053588867, -0.033081055, 0.020217896, 0.0028095245, 0.02178955, 0.040100098, -0.011497498, 0.010444641, -0.059509277, 0.08892822, -0.02508545, -0.0077705383, 0.005672455, -0.016021729, -0.025421143, -0.010231018, 0.02809143, -0.023986816, 0.008003235, 0.08709717, -0.022720337, -0.007335663, 0.0473938, 0.03414917, 5.6266785E-4, 0.018035889, -0.09240723, -0.01939392, -0.083984375, 0.025009155, -0.10675049, 0.009124756, -0.075927734, -0.04257202, 0.049743652, 0.019897461, -0.084472656, -0.053741455, 0.01499176, -0.013313293, -0.00919342, -0.008735657, -0.07513428, -0.034698486, 0.023254395, -0.03955078, 0.020889282, -0.0043296814, 0.042510986, -0.08532715, -0.004299164, -0.020706177, -0.100097656, 0.0014886856, 0.03375244, 0.10223389, -0.03387451, -0.021194458, -0.08734131, 0.0077705383, 0.021835327, -0.022918701, -0.08874512, -0.103393555, 0.018234253, -0.10003662, -0.024520874, 0.019088745, -0.011100769, -0.0090789795, -0.028717041, 0.007835388, 0.018066406, 0.06762695, 0.011154175, -0.033203125, 0.06262207, -0.008995056, -0.05255127, -0.007949829, -0.013938904, 0.055267334, -0.07922363, -0.0054244995, 0.012046814, -0.0307922