INSERT INTO document_vectors (id, content, embedding) VALUES ('01a0a12a-b694-7a8b-8aa9-77ccf9d1b461', '### The Defensive Investor

The primary goal of the defensive (or passive) investor is to minimize effort, avoid significant mistakes, and secure a satisfactory baseline return. Defensive investors achieve this by maintaining a simple asset allocation, such as an equal split between high-grade bonds and well-established blue-chip stocks or low-cost index funds. They prioritize companies with long track records of profitability, moderate debt levels, and continuous dividend payments over decades.', VEC_FromText('[0.031280518, 0.0413208, 0.039733887, 0.114746094, 0.028640747, 0.0084991455, -0.031982422, 0.061706543, -0.028182983, 0.097229004, 0.029953003, -0.015617371, 0.044281006, -0.101623535, 0.09515381, 0.07116699, 0.023330688, -0.032989502, -0.0597229, 0.07623291, -0.010643005, 0.01411438, -0.039398193, 0.057647705, 0.023620605, 0.009475708, -0.047180176, 0.009529114, 0.012260437, -0.016525269, 0.10559082, -0.03152466, -0.02017212, 0.017120361, 0.05911255, 0.034057617, -0.03378296, -0.015838623, 0.06719971, 0.02268982, -0.003982544, 0.0075149536, -0.046142578, -0.0418396, 0.0027656555, 0.013748169, 0.09552002, -0.056152344, 0.032226562, -0.0112838745, -0.13659668, -0.0062408447, 0.06604004, 0.12805176, 0.019958496, 0.07873535, -0.020492554, 0.007820129, -0.032043457, 0.035491943, 0.012306213, 0.029510498, 0.037322998, 0.056549072, -0.016098022, -0.021408081, -0.095825195, 0.10498047, -0.03250122, 0.041412354, -0.0068244934, -0.08428955, 0.018478394, -0.022033691, 0.041229248, -0.06304932, 0.011100769, -0.011787415, 0.016845703, 0.026977539, 0.024353027, 0.115112305, -0.10241699, 0.015419006, -0.056854248, -0.061706543, -0.022369385, 0.02368164, -0.066711426, -0.03765869, -0.093688965, 0.034820557, -0.008728027, -0.032562256, -0.07336426, -0.034942627, -0.0022010803, 0.024658203, -0.013946533, -0.024917603, -0.020004272, -0.009109497, -0.020751953, 0.030715942, 0.0014734268, -0.018447876, 0.07318115, -0.058532715, -0.056274414, -0.0019607544, -0.1239624, 0.009094238, 0.03289795, 0.09210205, 