INSERT INTO document_vectors (id, content, embedding) VALUES ('01a0a12a-b8cb-7359-94b3-cef3b080e4bf', '### The Enterprising Investor
The enterprising (or active) investor seeks to outperform market averages by devoting substantial time to security analysis, business valuation, and portfolio execution. Enterprising investors look for deeply undervalued securities, turnaround situations, or asset-rich companies trading at discounts to their net current asset value (often called "net-nets").', VEC_FromText('[0.01399231, -0.013069153, 0.03564453, 0.064941406, 0.050079346, 0.030136108, 0.022827148, 0.091552734, 0.03881836, 0.0569458, 0.0680542, 0.006969452, -2.2792816E-4, -0.045715332, 0.077941895, 0.034454346, -0.062561035, -0.047088623, -0.052764893, 0.072387695, 0.048553467, -0.027389526, -0.051513672, 0.06329346, -0.019088745, 0.043060303, -0.12213135, 0.07318115, -0.0072250366, -0.06555176, 0.0592041, -0.015991211, -0.041412354, -0.006626129, 0.04940796, 0.068237305, -0.024810791, -0.0748291, 0.069885254, -0.041656494, -0.006855011, -0.024291992, 0.014518738, -0.0064926147, 0.07531738, -0.062683105, 0.015975952, -0.1583252, 0.08154297, 0.022628784, -0.09387207, -0.031143188, 0.0137786865, 0.057861328, -0.023803711, -0.028793335, -0.056274414, -0.017349243, -0.05834961, 0.023498535, 0.0569458, 0.029891968, 0.034698486, 0.07714844, -0.03945923, -0.0075569153, -0.082214355, 0.11230469, -0.054992676, -0.0039253235, 0.023498535, -0.06201172, -0.0473938, -0.055023193, 0.020721436, -0.003850937, -0.042510986, -0.034362793, 0.022979736, -0.009513855, 0.06549072, 0.05126953, -0.036224365, 0.042236328, -0.036224365, -0.055877686, -0.030517578, -0.0569458, -0.004295349, -0.07312012, -0.021347046, 0.030761719, 0.031158447, 0.021118164, 0.06173706, 0.03515625, -0.023498535, -0.0014781952, 0.011016846, 0.036834717, 0.045654297, 0.037475586, -0.04385376, 0.0012311935, -0.005657196, 0.015052795, -0.01977539, -0.007671356, 0.005722046, -0.049102783, -0.113708496, -0.03451538, 0.047088623, 0.023666382, 0.049804688, -0.017623901, -0.058532715, 0.0024089813, 0.0027236938, -0.03527832, 0.01991272, -0.020721436, 0.026