INSERT INTO document_vectors (id, content, embedding) VALUES ('01a0a12b-1b30-72ee-bf7d-6c07b9435736', 'However, Graham cautions against assuming that common stocks are a perfect hedge against high inflation. Rising input costs and increased capital requirements can depress profit margins for many businesses during inflationary periods. Protection comes from owning shares in well-capitalized companies with strong pricing power or holding inflation-indexed government bonds.

---

