INSERT INTO document_vectors (id, content, embedding) VALUES ('01a0a12b-1c67-7c1f-a2bc-db4846c982a5', '* **Dynamic Allocation Splits:** A baseline distribution of 50% stocks and 50% bonds provides a balanced risk profile. Depending on market conditions, the equity exposure should range between a minimum of 25% and a maximum of 75%.
* **Rebalancing Discipline:** Investors should periodically adjust allocations back to target ratios on fixed schedule dates. Rebalancing systematically forces the investor to sell equities when prices are elevated and buy them when prices drop.', VEC_FromText('[0.008468628, 0.03967285, 0.1381836, 0.08532715, -0.009468079, -0.0068244934, -0.027908325, 0.08026123, 0.0018405914, 0.070129395, 0.05883789, -0.045715332, 0.04083252, -0.041107178, 0.11462402, 0.053771973, 0.022583008, -0.012016296, -0.11804199, 0.009185791, -0.078430176, 0.011062622, 0.048614502, 0.08618164, -4.799366E-4, -0.005947113, 0.00945282, -0.0519104, -0.019805908, -0.008094788, 0.13415527, -0.034484863, 0.03189087, -0.030853271, -0.00894165, 0.10638428, -0.032287598, 0.009239197, 0.093933105, -0.026031494, -0.01109314, -0.029190063, -0.047302246, 0.0077552795, -0.0035381317, 0.011657715, 0.005744934, -0.1116333, 0.040893555, 0.062683105, -0.11138916, -0.009231567, 0.0056610107, 0.005214691, 0.028335571, 0.05218506, -0.016906738, 0.048706055, 0.03604126, 0.054718018, 0.06121826, -0.0211792, 0.04208374, 0.048614502, 0.0027942657, -0.06274414, -0.086364746, 0.052612305, -0.013122559, 0.0345459, 0.004211426, 0.009529114, 0.06524658, 0.012123108, 0.014297485, -0.064941406, -4.0960312E-4, -0.04071045, -0.03994751, 0.02684021, 2.1457672E-4, 0.060791016, -0.060668945, 0.050933838, 0.06311035, -0.035369873, -0.025772095, -0.022399902, -0.09240723, 0.001540184, -0.08148193, -0.041900635, -0.01576233, 0.009941101, -0.0049362183, -0.12878418, 0.07531738, 0.012321472, -0.048461914, -0.022079468, 1.14142895E-4, -0.008613586, -0.082458496, -0.021896362, 0.0758667, -0.0015106201, 0.028961182, -0.015602112, -0.010246277, 0.011741638, -0.095336914, -0.014854431, 0.024658203, 0.052520752, -0.018478394, -0.07733154, -0.11810303, 0.10241699, -0.062683105, -0.008880615, -0.07922363, -0.051727295, 0.0574646, 0.011039734, -0.011795044, -0.0030078888, -0.013961792, -0.073791504, -0.08392334, 0.021530151, 0.031402588, 0.00