INSERT INTO document_vectors (id, content, embedding) VALUES ('01a0a12b-1efb-7a16-9b44-76b3341badd3', 'Investors frequently fall into destructive behavioral patterns: buying during speculative bull market peaks due to greed and selling during panic-driven bear market troughs. An intelligent investor must cultivate a contrarian mindset: viewing market rises with caution (as assets become more expensive and risky) and market declines with optimism (as sound companies go on sale).', VEC_FromText('[0.062469482, -0.03741455, 0.058776855, 0.122802734, 0.017730713, 0.070495605, 0.0079956055, 0.105285645, 0.02784729, 0.06573486, 0.08569336, -0.028717041, 0.034729004, -0.034362793, 0.095703125, 0.10021973, 0.0019187927, -0.058776855, -0.10858154, 0.06536865, -0.012428284, 0.07739258, -0.055877686, 0.02798462, -0.006958008, -0.015975952, -0.0435791, 0.0020389557, 0.08276367, 0.01838684, 0.1026001, -0.03604126, -0.019821167, 0.03201294, -0.051971436, 0.02154541, -0.01499176, -0.073913574, 0.07354736, -0.0073242188, 0.02458191, 0.020828247, 0.02482605, 0.0022850037, 0.10040283, -0.0053138733, 0.04437256, -0.10089111, 0.011451721, 0.06665039, -0.08685303, -0.04034424, 0.04925537, 0.066345215, -0.009384155, -0.02458191, -0.012763977, 0.062683105, -0.0019779205, 0.04232788, 0.08660889, -0.0066490173, 0.025848389, 0.04232788, -0.025619507, -0.056518555, -0.07244873, 0.060150146, -0.027435303, 0.077941895, 0.07476807, -0.090148926, -0.007873535, 0.06652832, 0.05895996, -0.029953003, 0.062469482, 0.0024662018, 0.04840088, 0.0031375885, 0.05307007, 0.027420044, -0.05810547, 0.026306152, -0.010513306, 0.04336548, 0.0028457642, -0.023498535, -0.006702423, -0.080444336, 0.0057678223, 0.04937744, 0.018295288, -0.02708435, -0.072753906, -0.0121536255, 0.05831909, 0.03060913, -0.020477295, 0.015411377, 0.025009155, -0.028457642, -0.021865845, 0.09161377, 0.07495117, -0.0127334595, -0.027511597, -0.03878784, -0.018920898, 0.024627686, -0.110839844, -0.017684937, -0.062927246, 0.023773193, -0