INSERT INTO document_vectors (id, content, embedding) VALUES ('01a0a12b-21dc-7761-8e4d-909300a426a8', '3. **Use Mr. Market to Your Advantage:** Take advantage of irrational market pricing without letting market mood swings dictate your financial behavior.
4. **Demand a Margin of Safety:** Minimize downside risk by purchasing securities at a discount relative to their intrinsic valuation.
